-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the guard ignores min_tier: any ON override on an individual plan is blocked
-- targets: c15
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._override_above_tier(
  p_feature_key text,
  p_min_tier    text,
  p_plan_tier   text,
  p_override    jsonb
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT COALESCE((p_override ->> 'enabled')::boolean, true)
     AND p_plan_tier = 'individual'
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._override_above_tier(text,text,text,jsonb)'::regprocedure) NOT LIKE '%p_min_tier IS NOT NULL%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('min_tier ignored') AS mutation;
